{
  "name": "rf_channel_calibrate",
  "confidence": "medium",
  "docstring": "Runs the hardware RF calibration sequence for a given channel, programs per-channel calibration entries and trigger registers, waits for completion, and returns the channel calibration table entry.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "channel",
    "v1": "rf_channel_table",
    "v2": "rf_channel_class",
    "v4": "rf_channel_entry",
    "v5": "rf_channel_aux_entry_ptr",
    "v6": "calibration_slot_index",
    "v7": "calibration_slot",
    "v10": "rf_class_entry",
    "v15": "rf_calibration_cmd_reg",
    "v16": "rf_calibration_cmd_reg",
    "v17": "rf_aux_entry",
    "v20": "rf_aux_channel_code",
    "v22": "rf_calibration_status_reg"
  },
  "struct_hints": [
    {
      "offset": 32,
      "meaning": "rf_channel_entry byte 32: band/class index used to select the RF class entry"
    },
    {
      "offset": 44,
      "meaning": "rf_channel_entry pointer at offset 44: auxiliary RF calibration entry for this channel"
    },
    {
      "offset": 56,
      "meaning": "rf_channel_entry array at offset 56: first set of four calibration entries or pointers"
    },
    {
      "offset": 88,
      "meaning": "rf_channel_entry array at offset 88: second set of four calibration entries or pointers"
    },
    {
      "offset": 94,
      "meaning": "rf_class_entry byte 94: calibration state byte; 2 means already complete, 0 means clear result"
    },
    {
      "offset": 102,
      "meaning": "rf_class_entry byte 102: calibration result/error byte, set to -1 when calibration is invalid or not configured"
    },
    {
      "offset": 33,
      "meaning": "rf_aux_entry byte 33: auxiliary channel code used to form the second RF calibration command"
    }
  ]
}
